"""A target chooser that simply picks the first from the given list

    This is the default, particularly for the case of only one element in
    the list
    """
def first(targets: Any, cat: Any, kwargs: Any) -> object {
    targ = targets[0];
    if cat {
        s = cat[targ];
        if (kwargs and (targ in kwargs)) {
            s = kwargs.configure_new(**kwargs[targ]);
        }
        return s;
    } else {
        return targ;
    }
}

"""
    Check if the given file is a ZIP
    Returns:
        bool: Whether it's a ZIP file or not
    """
def is_zip(file_type: Any) -> bool {
    mimes = {
        'application/zip',
        'application/octet-stream',
        'application/x-zip-compressed',
        'multipart/x-zip'
    };
    for v in mimes {
        if (v == file_type) {
            return True;
        }
    }
    return False;
}

